package com.fileservice.processing

import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.time.Instant
import java.time.Duration

data class RateLimitEntry(
    val count: AtomicInteger = AtomicInteger(0),
    @Volatile var windowStart: Long = System.currentTimeMillis()
)

class RateLimiter(
    private val maxRequests: Int = 10,
    private val windowMs: Long = 60_000
) {
    private val entries = ConcurrentHashMap<String, RateLimitEntry>()
    private val mutex = Mutex()

    suspend fun tryAcquire(clientId: String): Boolean {
        val entry = entries.computeIfAbsent(clientId) { RateLimitEntry() }

        mutex.withLock {
            val now = System.currentTimeMillis()
            if (now - entry.windowStart > windowMs) {
                entry.count.set(0)
                entry.windowStart = now
            }
            val currentCount = entry.count.incrementAndGet()
            return currentCount <= maxRequests
        }
    }

    fun getRemaining(clientId: String): Int {
        val entry = entries[clientId] ?: return maxRequests
        return (maxRequests - entry.count.get()).coerceAtLeast(0)
    }
}

data class FileProcessingRequest(
    val clientId: String,
    val fileName: String,
    val content: ByteArray,
    val priority: Int = 0
)

sealed class ProcessingResult {
    data class Success(val outputPath: String, val processingTimeMs: Long) : ProcessingResult()
    data class RateLimited(val retryAfterMs: Long) : ProcessingResult()
    data class Error(val message: String) : ProcessingResult()
}

class FileProcessingService(
    private val rateLimiter: RateLimiter = RateLimiter(),
    private val maxConcurrent: Int = 5
) {
    private val processingScope = CoroutineScope(Dispatchers.IO + SupervisorJob())
    private val activeTasks = AtomicInteger(0)
    private val taskResults = ConcurrentHashMap<String, Deferred<ProcessingResult>>()

    suspend fun submitFile(request: FileProcessingRequest): ProcessingResult {
        val normalizedClientId = normalizeClientId(request.clientId)

        if (!rateLimiter.tryAcquire(normalizedClientId)) {
            val remaining = rateLimiter.getRemaining(normalizedClientId)
            return ProcessingResult.RateLimited(
                retryAfterMs = calculateRetryDelay(remaining)
            )
        }

        if (activeTasks.get() >= maxConcurrent) {
            return ProcessingResult.Error("Server at capacity, please retry later")
        }

        val taskId = generateTaskId(request)
        val deferred = processingScope.async {
            processFileInternal(request)
        }
        taskResults[taskId] = deferred

        return try {
            deferred.await()
        } finally {
            taskResults.remove(taskId)
        }
    }

    suspend fun submitBatch(requests: List<FileProcessingRequest>): List<ProcessingResult> {
        return coroutineScope {
            requests.map { request ->
                async {
                    submitFile(request)
                }
            }.map { it.await() }
        }
    }

    private suspend fun processFileInternal(request: FileProcessingRequest): ProcessingResult {
        activeTasks.incrementAndGet()
        try {
            val startTime = System.currentTimeMillis()

            // Simulate file processing with validation
            validateFileContent(request.content)
            delay(100 + (request.content.size / 1024).toLong())

            // Sanitize path components to prevent path traversal (CWE-22)
            val safeClientId = sanitizePathComponent(normalizeClientId(request.clientId))
            val safeFileName = sanitizePathComponent(request.fileName)
            if (safeClientId.isEmpty() || safeFileName.isEmpty()) {
                return ProcessingResult.Error("Invalid client id or file name")
            }
            val outputPath = "/processed/$safeClientId/$safeFileName.out"
            val elapsed = System.currentTimeMillis() - startTime

            return ProcessingResult.Success(outputPath, elapsed)
        } catch (e: Exception) {
            return ProcessingResult.Error("Processing failed: ${e.message}")
        } finally {
            activeTasks.decrementAndGet()
        }
    }

    private fun normalizeClientId(clientId: String): String {
        // Normalize unicode and trim whitespace for consistent rate limiting
        return clientId
            .trim()
            .lowercase()
            .replace(Regex("[^a-z0-9._@-]"), "")
    }

    private fun sanitizePathComponent(input: String): String {
        // Strip any path separators and traversal sequences to prevent path traversal
        return input
            .replace("\\", "")
            .replace("/", "")
            .replace("..", "")
            .replace(Regex("[^A-Za-z0-9._@-]"), "")
            .trim()
    }

    private fun validateFileContent(content: ByteArray) {
        require(content.isNotEmpty()) { "File content cannot be empty" }
        require(content.size <= 10 * 1024 * 1024) { "File too large (max 10MB)" }
    }

    private fun calculateRetryDelay(remaining: Int): Long {
        return if (remaining <= 0) 60_000L else 5_000L
    }

    private fun generateTaskId(request: FileProcessingRequest): String {
        return "${request.clientId}_${request.fileName}_${System.nanoTime()}"
    }

    fun shutdown() {
        processingScope.cancel()
    }
}
